scss.scss_field:
  .row > .images + .texte.mt-5 {
    margin-top: 0 !important;
  }
  .vixon-heading{
        display: flex;
    flex-direction: column;
    min-height: 100%;
    justify-content: center;
    @include media-min(DD) {
       max-width:390px;
      margin-left: auto;
      margin-right: auto;
      .head-title,.title-description{
        margin-left: 0 !important;
      }
    }
}
  
  .vixon-heading .stroked-text{
    -webkit-text-stroke-width: unset;
    color: inherit;
    // @include media-min(DD) {
    //  margin-left: $wbu-margin * 6.5;
   // }
  }
  .about-img {
  box-shadow: unset;
  .img-block{
  border: 0;
    max-width: 200px; 
    min-width:180px;
    width:100%;
  bottom: auto;
  top: 50%;
  transform: translateY(-50%);
  left: auto;
  right: 0;
    @include media-min(MD) {
      max-width: 300px;
    }
    @include media-min(DD) {
right: -80px;
      max-width: 220px;
    }
  }
  .second_image{
    img{
      max-width:calc(100% - 80px);
    }
  }
}

